def rank_transforms(H,W,inside,outside):
    def maps(r,c): return [(r,c),(r,W-1-c),(H-1-r,c),(H-1-r,W-1-c),(c,r),(c,H-1-r),(W-1-c,r),(W-1-c,H-1-r)]
    colors=sorted(inside)
    scores=[]
    for k in range(8):
        s=0
        for i,x in enumerate(colors):
            for y in colors[i+1:]:
                a,b=maps(*inside[x])[k],maps(*inside[y])[k]
                v=(b[0]-a[0],b[1]-a[1]); q=(outside[y][0]-outside[x][0],outside[y][1]-outside[x][1])
                s+=(v[0]*q[0]+v[1]*q[1])/(math.hypot(*v)*math.hypot(*q))
        scores.append(s/3)
    return sorted(enumerate(scores),key=lambda z:-z[1])
print('demo1',rank_transforms(9,10,{2:(1,1),4:(1,8),3:(7,8)},{3:(14,8),4:(14,14),2:(21,14)}))
